CREATE DATABASE BusinessAnalytics;
GO

USE BusinessAnalytics;
GO

IF OBJECT_ID('dbo.Sales_Data','U') IS NOT NULL DROP TABLE dbo.Sales_Data;
GO

CREATE TABLE dbo.Sales_Data (
Order_ID VARCHAR(20), Order_Date DATE, Customer_ID VARCHAR(20), Customer_Name VARCHAR(100),
City VARCHAR(100), Region VARCHAR(50), Customer_Segment VARCHAR(50), Product_ID VARCHAR(20),
Product_Name VARCHAR(100), Category VARCHAR(50), Subcategory VARCHAR(50), Quantity INT,
Unit_Price DECIMAL(18,2), Discount_Percent DECIMAL(8,4), Gross_Sales DECIMAL(18,2),
Discount_Amount DECIMAL(18,2), Net_Sales DECIMAL(18,2), Cost DECIMAL(18,2),
Profit DECIMAL(18,2), Sales_Channel VARCHAR(50), Sales_Rep VARCHAR(100),
Payment_Method VARCHAR(50), Order_Status VARCHAR(50), Profit_Margin_Percent DECIMAL(10,6)
);
GO


SELECT * FROM dbo.Sales_Data
SELECT COUNT(*) AS Total_Rows FROM dbo.Sales_Data;
SELECT TOP 10 * FROM dbo.Sales_Data;

SELECT SUM(Net_Sales) AS Total_Net_Sales, 
SUM(Profit) AS Total_Profit, 
COUNT(DISTINCT Order_ID) AS Total_Orders,
SUM(Quantity) AS Total_Quantity
FROM dbo.Sales_Data;

SELeCT top 5 * FROM dbo.Sales_Data
ORDER BY Net_sales desc

select * from dbo.sales_data

select max(net_sales) as max_sales from dbo.sales_data
 select min(net_sales) as min_sales from dbo.sales_data
	
 select 
 sum(profit)*100/nullif(sum(net_sales),0) as profit_margin_percent
 from dbo.sales_data

 select region,
 sum(net_sales) as total_sales,
 sum(profit) as total_profit,
 count(distinct Order_ID) as total_orders
 from dbo.sales_data
 group by region 
 order by total_sales desc

 
 select 
 product_name,
 sum(net_sales) as total_sales,
 sum(profit) as total_profit
 from dbo.sales_data
 group by product_name

 select top 5
 product_name,
 sum(net_sales) as total_sales,
 sum(profit) as total_profit
 from dbo.sales_data
 group by product_name
 order by total_sales desc

 SELECT TOP 5
 CUSTOMER_NAME,
 SUM(NET_SALES) AS TOTAL_SALES
 FROM DBO.SALES_DATA
 GROUP BY CUSTOMER_NAME
 ORDER BY TOTAL_SALES DESC

 select 
  format(order_date, 'yyyy-MM') as sales_month,
  sum(net_sales) as total_sales,
  sum(profit) as total_profit,
  SUM(QUANTITY) AS TOTAL_QUANTITY
 from dbo.sales_data
 group by format(order_date,'yyyy-MM')
 order by sales_month

SELECT Customer_Name,
SUM(NET_SALES) AS TOTAL_SALES
FROM dbo.Sales_Data
group by customer_name
HAVING SUM(NET_SALES)>
(
SELECT AVG(CUSTOMER_SALES)
FROM  
( SELECT Customer_ID,
SUM(NET_SALES) AS CUSTOMER_SALES
FROM dbo.sales_data
GROUP BY CUSTOMER_ID
) AS CUSTOMERSUMMARY
)
ORDER BY TOTAL_SALES DESC


select product_name,
sum(net_sales) as total_sales,
rank() over(order by sum(net_sales) desc) as sales_rank
from dbo.sales_data
group by product_name
order by total_sales desc

select region,
sum(net_sales) as total_sales,
sum(net_sales)*100/ sum(sum(net_sales)) over() as sales_percentage
from dbo.sales_data
group by region
order by sales_percentage

select Sales_Channel,
sum(net_sales) as total_sales,
sum(profit)as total_profit
from dbo.sales_data
where sales_channel in ('online','retail', 'partner')
group by sales_channel
order by total_sales desc;


select category,
sum(quantity) as total_quantity
from dbo.sales_data
group by category
order by total_quantity desc;

select max(net_sales) as second_highest_sales
from dbo.sales_data
where net_sales <(
select max(net_sales) from dbo.sales_data
);

select order_id,
count(*) as duplicate_count
from dbo.sales_data
 group by order_id
 having count (*) >1;